<script setup lang="ts">
import {reactive,ref} from 'vue';
import {message} from 'ant-design-vue';
import {api} from '../services/api';
import type{Playbook,ResourceOwnerType} from '../types';
import type{OwnershipOption} from '../composables/ownership';
import OwnershipFields from '../components/OwnershipFields.vue';
const props=defineProps<{playbooks:Playbook[];ownershipOptions:OwnershipOption[];currentUserId:string}>();const emit=defineEmits<{refreshCatalog:[]}>();
const open=ref(false),saving=ref(false);const target=ref<Playbook|null>(null);const form=reactive({name:'',description:'',ownerType:'PERSON' as ResourceOwnerType,ownerId:''});
function edit(item?:Playbook){target.value=item??null;Object.assign(form,item??{name:'',description:'',ownerType:'PERSON',ownerId:props.currentUserId});open.value=true;}
async function save(){if(!form.name.trim())return void message.error('请输入名称。');saving.value=true;try{const metadata={name:form.name,description:form.description,ownerType:form.ownerType,ownerId:form.ownerId};if(target.value)await api.updatePlaybook(target.value.id,metadata);else await api.createPlaybook({...metadata,initialVersion:{status:'DRAFT',definition:{description:form.description,inputSchema:'{}',resultSchema:'{}',executionPolicy:{timeoutPolicy:null,retryPolicy:null},allowHumanTask:true,allowExternalInteraction:true,entryNodeKey:'done',nodes:[{nodeKey:'done',nodeName:'完成',nodeType:'END',description:null,scriptRef:null,scriptVersion:null,toolId:null,toolOperation:null,config:{},layout:{x:120,y:100}}],edges:[]}}});open.value=false;emit('refreshCatalog');}catch(e){void message.error(e instanceof Error?e.message:String(e));}finally{saving.value=false;}}
async function publish(id:string,version:string){try{await api.publishPlaybookVersion(id,version);emit('refreshCatalog');}catch(e){void message.error(e instanceof Error?e.message:String(e));}}
async function remove(id:string){try{await api.deletePlaybook(id);emit('refreshCatalog');}catch(e){void message.error(e instanceof Error?e.message:String(e));}}
</script><template><a-card title="Playbook"><template #extra><a-button type="primary" @click="edit()">创建 Playbook</a-button></template><a-alert type="info" show-icon message="Playbook 是独立版本化的执行定义，可供不同角色调用。运行中的人工等待和外部回调由 ToolRun 持续记录。" style="margin-bottom:20px"/><a-empty v-if="!playbooks.length" description="尚无 Playbook"/><a-collapse><a-collapse-panel v-for="item in playbooks" :key="item.id" :header="item.name"><p>{{item.description}}</p><a-space><router-link :to="{path:'/console/playbooks/editor',query:{playbookId:item.id}}">编辑流程图并创建版本</router-link><a-button @click="edit(item)">基本信息</a-button><a-popconfirm title="删除此 Playbook？已发布版本受到保护。" @confirm="remove(item.id)"><a-button danger>删除</a-button></a-popconfirm></a-space><a-list :data-source="item.versions"><template #renderItem="{item:version}"><a-list-item><a-space><strong>{{version.version}}</strong><a-tag>{{version.status==='PUBLISHED'?'已发布':'草稿'}}</a-tag><span>{{version.definition.nodes.length}} 节点</span></a-space><a-button v-if="version.status==='DRAFT'" @click="publish(item.id,version.id)">发布版本</a-button></a-list-item></template></a-list></a-collapse-panel></a-collapse></a-card><a-modal v-model:open="open" :title="target?'编辑 Playbook 信息':'创建 Playbook'" :confirm-loading="saving" @ok="save"><a-form layout="vertical"><a-form-item label="名称" required><a-input v-model:value="form.name"/></a-form-item><a-form-item label="描述"><a-textarea v-model:value="form.description"/></a-form-item><OwnershipFields v-model:owner-type="form.ownerType" v-model:owner-id="form.ownerId" :options="ownershipOptions"/></a-form></a-modal></template>
